            name: $entity->getName(),
            icon: $entity->getIcon(),
            deviceId: $entity->getDeviceId(),
            payload: $entity->getPayload(),
            isDefault: $entity->isDefault(),
            sortOrder: $entity->getSortOrder(),
            version: $entity->getVersion(),
            createdAt: $entity->getCreatedAt(),
            updatedAt: $entity->getUpdatedAt(),
