    ) {
    }

    public function getAccentColor(Uuid $userId): ?string
    {
        $entity = $this->entityManager
            ->getRepository(UserAccentColorEntity::class)
            ->findOneBy(['userId' => $userId]);

        return $entity?->getAccentColor();
    }

